/// @dev Harvest fees, take the performance fee, re-add the rest plus idle dust as liquidity.
/// Leaves this contract's PoolManager balance at zero.
function _compound(Vault storage v, PoolId id, bytes memory hookData) internal {
    v.lastCompound = uint64(block.timestamp);
    if (v.liquidity == 0) return;
    (BalanceDelta fees,) = poolManager.modifyLiquidity(
        v.key, ModifyLiquidityParams(v.tickLower, v.tickUpper, 0, bytes32(0)), hookData
    );
    uint256 f0 = fees.amount0() > 0 ? uint128(fees.amount0()) : 0;
    uint256 f1 = fees.amount1() > 0 ? uint128(fees.amount1()) : 0;
    uint256 cut0 = (f0 * perfFeeBps) / BPS;
    uint256 cut1 = (f1 * perfFeeBps) / BPS;
    _take(v.key.currency0, treasury, cut0);
    _take(v.key.currency1, treasury, cut1);

    uint256 r0 = f0 - cut0 + v.idle0;
    uint256 r1 = f1 - cut1 + v.idle1;
    int256 net0 = int256(f0 - cut0);
    int256 net1 = int256(f1 - cut1);
    uint128 liq;
    if (r0 > 2 || r1 > 2) {
        (uint160 sqrtP,,,) = poolManager.getSlot0(id);
        liq = LiquidityAmounts.getLiquidityForAmounts(
            sqrtP,
            TickMath.getSqrtPriceAtTick(v.tickLower),
            TickMath.getSqrtPriceAtTick(v.tickUpper),
            r0 > 2 ? r0 - 2 : 0,
            r1 > 2 ? r1 - 2 : 0
        );
    }
    if (liq > 0) {
        (BalanceDelta d,) = poolManager.modifyLiquidity(
            v.key, ModifyLiquidityParams(v.tickLower, v.tickUpper, int256(uint256(liq)), bytes32(0)), hookData
        );
        v.liquidity += liq;
        net0 += d.amount0();
        net1 += d.amount1();
    }
    // Positive net = fee credit left over -> hold it here as idle. Negative = idle was used -> pay it in.
    v.idle0 = uint256(int256(v.idle0) + net0);
    v.idle1 = uint256(int256(v.idle1) + net1);
    _settle(v.key.currency0, net0, address(this));
    _settle(v.key.currency1, net1, address(this));
    if (f0 > 0 || f1 > 0) emit Compounded(id, f0, f1, liq);
}

