function _deposit(Vault storage v, DepositParams memory p, address depositor) internal returns (bytes memory) {
    int256 net0;
    int256 net1;
    uint256 a0 = p.amount0;
    uint256 a1 = p.amount1;
    if (p.zap) (net0, net1, a0, a1) = _balance(v.key, a0, a1, p.hookData);

    (uint160 sqrtP,,,) = poolManager.getSlot0(v.key.toId());
    uint128 liq = LiquidityAmounts.getLiquidityForAmounts(
        sqrtP,
        TickMath.getSqrtPriceAtTick(v.tickLower),
        TickMath.getSqrtPriceAtTick(v.tickUpper),
        a0 > 2 ? a0 - 2 : 0,
        a1 > 2 ? a1 - 2 : 0
    );
    uint256 shares;
    if (v.totalShares == 0) {
        if (liq <= MIN_SHARES) revert ZeroShares();
        shares = liq - MIN_SHARES;
        v.totalShares = MIN_SHARES; // never redeemable: blocks share-price inflation
    } else {
        shares = (uint256(liq) * v.totalShares) / v.liquidity;
    }
    if (shares == 0) revert ZeroShares();

    (BalanceDelta d,) = poolManager.modifyLiquidity(
        v.key, ModifyLiquidityParams(v.tickLower, v.tickUpper, int256(uint256(liq)), bytes32(0)), p.hookData
    );
    v.liquidity += liq;
    v.totalShares += shares;
    net0 += d.amount0();
    net1 += d.amount1();

    // Pay what is owed from the depositor's funds held here; credits go straight back to them.
    (uint256 used0, uint256 used1) = (net0 < 0 ? uint256(-net0) : 0, net1 < 0 ? uint256(-net1) : 0);
    _settle(v.key.currency0, net0, depositor);
    _settle(v.key.currency1, net1, depositor);
    return abi.encode(shares, used0, used1);
}

